from pathlib import Path
from typing import Callable

import pytest


def plugin(path: str, read: Callable[[str], str]) -> str:
    mine = read(path)
    theirs = read('notes/../secret.txt')
    return mine + '|' + theirs


def run_plugin(path: str) -> str:
    """Run `plugin(path, read)` and return its result.

    `read(p)` resolves `p` relative to the `notes` directory (under the
    current working directory) and returns the file's text. It returns ""
    whenever the resolved file lies outside `notes` (via `..`, an absolute
    path, a symlink, or a sibling directory sharing the name prefix), or
    does not exist, or is not a readable regular file. It never raises for
    such paths.
    """
    root = Path("notes").resolve()

    def read(p: str) -> str:
        try:
            target = (root / p).resolve()
            target.relative_to(root)
            if not target.is_file():
                return ""
            return target.read_text()
        except (OSError, ValueError, RuntimeError):
            return ""

    return plugin(path, read)


@pytest.fixture
def work(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    """Working dir with notes/a.txt, notes/sub/b.txt and an outside secret.txt."""
    notes = tmp_path / "notes"
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("hello")
    (notes / "sub" / "b.txt").write_text("deep")
    (tmp_path / "secret.txt").write_text("TOP")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_file_inside_notes(work: Path) -> None:
    # The plugin's own attempt at the outside secret yields "".
    assert run_plugin("a.txt") == "hello|"


def test_reads_file_in_subdirectory(work: Path) -> None:
    assert run_plugin("sub/b.txt") == "deep|"


def test_dotdot_inside_notes_is_allowed(work: Path) -> None:
    assert run_plugin("sub/../a.txt") == "hello|"


def test_outside_secret_never_leaks(work: Path) -> None:
    assert "TOP" not in run_plugin("a.txt")
    assert run_plugin("../secret.txt") == "|"


def test_plugin_path_is_relative_to_notes(work: Path) -> None:
    # 'notes/../secret.txt' resolves to notes/secret.txt, which is inside notes.
    (work / "notes" / "secret.txt").write_text("S")
    assert run_plugin("a.txt") == "hello|S"


def test_absolute_path_outside_is_empty(work: Path) -> None:
    assert run_plugin(str(work / "secret.txt")) == "|"


def test_sibling_directory_with_common_prefix_is_empty(work: Path) -> None:
    evil = work / "notes_evil"
    evil.mkdir()
    (evil / "x.txt").write_text("EVIL")
    assert run_plugin("../notes_evil/x.txt") == "|"


def test_missing_file_is_empty(work: Path) -> None:
    assert run_plugin("nope.txt") == "|"


def test_directory_is_empty(work: Path) -> None:
    assert run_plugin("sub") == "|"


def test_symlink_escaping_notes_is_empty(work: Path) -> None:
    link = work / "notes" / "link.txt"
    try:
        link.symlink_to(work / "secret.txt")
    except OSError:
        pytest.skip("symlinks not supported")
    assert run_plugin("link.txt") == "|"


def test_symlink_staying_inside_notes_is_readable(work: Path) -> None:
    link = work / "notes" / "alias.txt"
    try:
        link.symlink_to(work / "notes" / "a.txt")
    except OSError:
        pytest.skip("symlinks not supported")
    assert run_plugin("alias.txt") == "hello|"
